51	  const intl = useIntl();
52	
53	  const handleQuantityChange = (stringValue: string, numberValue: number) => {
54	    // Set the Quantity of product to value of input if value number
55	    if (numberValue >= 0) {
56	      // Call handler — Promise.resolve(...) normalises a synchronous boolean return the same way
57	      // as a real Promise<boolean>, so a caller can supply either shape safely. `void`: this
58	      // handler is a synchronous event callback (base QuantityPicker's onChange contract), not
59	      // awaited by its own caller either — the promise is intentionally fire-and-forget.
60	      void Promise.resolve(onItemQuantityChange(numberValue)).then(
61	        (isValidChange: boolean) => isValidChange && setQuantity(numberValue),
62	      );
63	    } else if (stringValue === '') {
64	      // We want to allow the use to clear the input to start a new input so here we set the quantity to '' so NAN is not displayed
65	      // User will not be able to add '' quantity to the cart due to the add to cart button enablement rules
66	      setQuantity(stringValue);
67	    }
68	  };
69	
