1	import React from 'react';
2	import { describe, test, expect, vi } from 'vitest';
3	import { render, screen, fireEvent } from '@testing-library/react';
4	import { ChakraProvider } from '@chakra-ui/react';
5	import { IntlProvider } from 'react-intl';
6	import theme from 'app/theme';
7	import { ZimmQuantityStepper } from './index';
8	import { ZimmQuantityStepper as ZimmQuantityStepperRecipe } from './zimmQuantityStepper.css';
9	import { Button } from 'app/components/ui-kits/atoms/zimmButton/zimmButton.css';
10	import { spacing } from 'app/theme/foundation/spacing';
11	import { OPACITY_ICON_DISABLED } from 'app/components/ui-kits/zimmCartItemShared';
12	
13	// ZimmIcon imports the base SFCC icons barrel, which throws under Vitest (SVG imports resolve to
14	// raw path strings in this environment, not components) — see testing.md's Known gap. ZimmButton
15	// itself renders for real in every test below (not mocked): only its own leaf icon is stubbed, so
16	// the real ariaDisabled/onClick-suppression wiring this suite depends on is genuinely exercised
17	// end-to-end, not assumed from ZimmButton's own separate test suite.
18	vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
19	
20	const DECREMENT_NAME = 'Decrease quantity';
21	const INCREMENT_NAME = 'Increase quantity';
22	
23	const renderStepper = (props: Partial<React.ComponentProps<typeof ZimmQuantityStepper>> = {}) => {
24	  const onDecrement = vi.fn();
25	  const onIncrement = vi.fn();
26	  render(
27	    <IntlProvider locale="en">
28	      <ChakraProvider theme={theme}>
29	        <ZimmQuantityStepper quantity={3} max={5} onDecrement={onDecrement} onIncrement={onIncrement} {...props} />
30	      </ChakraProvider>
31	    </IntlProvider>,
32	  );
33	  return { onDecrement, onIncrement };
34	};
35	
36	describe('ZimmQuantityStepper — quantity = 1 (min boundary, State 1)', () => {
37	  test('decrement button carries aria-disabled="true"', () => {
38	    renderStepper({ quantity: 1 });
39	    expect(screen.getByRole('button', { name: DECREMENT_NAME })).toHaveAttribute('aria-disabled', 'true');
40	  });
41	
42	  test('clicking decrement at quantity 1 does NOT call onDecrement — quantity stays 1', () => {
43	    const { onDecrement } = renderStepper({ quantity: 1 });
44	    fireEvent.click(screen.getByRole('button', { name: DECREMENT_NAME }));
45	    expect(onDecrement).not.toHaveBeenCalled();
46	    expect(screen.getByText('1')).toBeInTheDocument();
47	  });
48	
49	  test('increment button is NOT disabled when only the lower bound is hit', () => {
50	    renderStepper({ quantity: 1, max: 5 });
51	    expect(screen.getByRole('button', { name: INCREMENT_NAME })).not.toHaveAttribute('aria-disabled', 'true');
52	  });
53	});
54	
55	describe('ZimmQuantityStepper — quantity > 1, below max (State 2, both enabled)', () => {
56	  test('decrement calls onDecrement with exactly quantity - 1, exactly once', () => {
57	    const { onDecrement } = renderStepper({ quantity: 3, max: 5 });
58	    fireEvent.click(screen.getByRole('button', { name: DECREMENT_NAME }));
59	    expect(onDecrement).toHaveBeenCalledTimes(1);
60	    expect(onDecrement).toHaveBeenCalledWith(2);
61	  });
62	
63	  test('increment calls onIncrement with exactly quantity + 1, exactly once', () => {
64	    const { onIncrement } = renderStepper({ quantity: 3, max: 5 });
65	    fireEvent.click(screen.getByRole('button', { name: INCREMENT_NAME }));
66	    expect(onIncrement).toHaveBeenCalledTimes(1);
67	    expect(onIncrement).toHaveBeenCalledWith(4);
68	  });
69	
70	  test('neither button carries aria-disabled', () => {
71	    renderStepper({ quantity: 3, max: 5 });
72	    expect(screen.getByRole('button', { name: DECREMENT_NAME })).not.toHaveAttribute('aria-disabled', 'true');
73	    expect(screen.getByRole('button', { name: INCREMENT_NAME })).not.toHaveAttribute('aria-disabled', 'true');
74	  });
75	});
76	
77	describe('ZimmQuantityStepper — quantity at max (State 3)', () => {
78	  test('increment button carries aria-disabled="true"', () => {
79	    renderStepper({ quantity: 5, max: 5 });
80	    expect(screen.getByRole('button', { name: INCREMENT_NAME })).toHaveAttribute('aria-disabled', 'true');
81	  });
82	
83	  test('clicking increment at max does NOT call onIncrement — quantity stays at max', () => {
84	    const { onIncrement } = renderStepper({ quantity: 5, max: 5 });
85	    fireEvent.click(screen.getByRole('button', { name: INCREMENT_NAME }));
86	    expect(onIncrement).not.toHaveBeenCalled();
87	    expect(screen.getByText('5')).toBeInTheDocument();
88	  });
89	
90	  test('decrement remains enabled at the max boundary', () => {
91	    renderStepper({ quantity: 5, max: 5 });
92	    expect(screen.getByRole('button', { name: DECREMENT_NAME })).not.toHaveAttribute('aria-disabled', 'true');
93	  });
94	});
95	
96	describe('ZimmQuantityStepper — isUnavailable (State 4, fully OOS/unavailable)', () => {
97	  test('both buttons carry aria-disabled="true", even mid-range (not just at a quantity bound)', () => {
98	    renderStepper({ quantity: 3, max: 5, isUnavailable: true });
99	    expect(screen.getByRole('button', { name: DECREMENT_NAME })).toHaveAttribute('aria-disabled', 'true');
100	    expect(screen.getByRole('button', { name: INCREMENT_NAME })).toHaveAttribute('aria-disabled', 'true');
101	  });
102	
103	  test('clicking either button calls neither callback — both are inert', () => {
104	    const { onDecrement, onIncrement } = renderStepper({ quantity: 3, max: 5, isUnavailable: true });
105	    fireEvent.click(screen.getByRole('button', { name: DECREMENT_NAME }));
106	    fireEvent.click(screen.getByRole('button', { name: INCREMENT_NAME }));
107	    expect(onDecrement).not.toHaveBeenCalled();
108	    expect(onIncrement).not.toHaveBeenCalled();
109	    expect(screen.getByText('3')).toBeInTheDocument();
110	  });
111	});
112	
113	describe('ZimmQuantityStepper — accessible names (State 6)', () => {
114	  test('decrement and increment buttons each resolve a distinct, real accessible name', () => {
115	    renderStepper({ quantity: 3, max: 5 });
116	    // getByRole with `name` already fails if the accessible name is missing/wrong — these two
117	    // succeeding proves both aria-labels are present, not merely that *some* button exists.
118	    expect(screen.getByRole('button', { name: DECREMENT_NAME })).toBeInTheDocument();
119	    expect(screen.getByRole('button', { name: INCREMENT_NAME })).toBeInTheDocument();
120	  });
121	});
122	
123	/**
124	 * States 5 and 7 are both about ZimmButton's own `icon` variant/size — a Tier 2 file this build
125	 * step composes but does not modify (see index.tsx's docblock). Reading the exported recipe
126	 * object directly proves the real, resolved theme values without rendering (per this step's own
127	 * brief: "assert this from the recipe/theme's resolved values, not by rendering in an actual
128	 * browser") and without re-testing what zimmButton's own suite already covers.
129	 */
130	describe('ZimmButton icon variant — resolved theme values (composed here, State 5 & 7)', () => {
131	  test('State 7 — icon touch target minW/minH both resolve to var(--zimm-scale-xl)', () => {
132	    // Button.sizes is typed optional by Chakra's defineStyleConfig, but zimmButton.css.ts always
133	    // passes a sizes object with an `icon` entry — guaranteed non-null at runtime. Same
134	    // justification zimmButton.css.test.ts's own `Button.sizes!.social` assertions already use.
135	    const icon = Button.sizes!.icon as Record<string, unknown>;
136	    expect(icon.minW).toBe('var(--zimm-scale-xl)');
137	    expect(icon.minH).toBe('var(--zimm-scale-xl)');
138	  });
139	
140	  test('State 7 — var(--zimm-scale-xl) resolves to at least 24 CSS px (WCAG 2.2 AA SC 2.5.8)', () => {
141	    // foundation/spacing.ts's `xl` is the source `--zimm-scale-xl` derives from (see
142	    // zimmTokens.ts's "reference, not a second copy" pattern) — confirmed here as 1.5rem, which
143	    // is 24px at the browser default 16px root font-size.
144	    const REM_TO_PX = 16;
145	    expect(spacing.xl).toBe('1.5rem');
146	    expect(parseFloat(spacing.xl) * REM_TO_PX).toBeGreaterThanOrEqual(24);
147	  });
148	
149	  test('State 5 — icon variant _disabled opacity equals the SAME OPACITY_ICON_DISABLED this stepper reads for its own value display', () => {
