1	/**
2	 * SFCC-795 (plan step 3.2). This atom's own render contract: does `aria-live="polite"` actually
3	 * render, does `data-testid` exist, does `text` render verbatim, and does `variant` actually
4	 * reach `useMultiStyleConfig` (proving the two variants resolve to genuinely different values,
5	 * not just that two differently-named keys exist in the recipe). Per testing.md's own guidance,
6	 * this contract must be provable from this component's own folder, not only incidentally via
7	 * product-item/index.test.tsx (which doesn't assert aria-live at all).
8	 *
9	 * SFCC-795 rework (Marcel's own visual checkpoint against the real Figma file): the `warning`
10	 * variant now renders a leading icon, `error` never does. `ZimmIcon` genuinely throws under real
11	 * Vitest rendering — it imports the base SFCC icons barrel, which has a top-level side effect
12	 * incompatible with this test environment (testing.md's documented "Known gap: ZimmIcon throws
13	 * under Vitest") — so it's mocked at the smallest surface, the same established pattern
14	 * footerNavColumn/index.test.tsx and zimmSubscribeSection/index.test.tsx already use, adjusted
15	 * here to forward `type` (rather than `aria-label`/`aria-hidden`, which neither of those two
16	 * examples needed to check) since the two new tests below assert on exactly that.
17	 *
18	 * SFCC-795 plan step 3.3 (2026-09-18, Marcel's direct Figma inspector pull for the discount-label
19	 * node): extends this file with the third variant, `success` (no icon, same as `error`), and with
20	 * `dataTestId`'s override-vs-default contract — added because a single cart line can now render
21	 * both a discount label and an error/warning message at once, and two ZimmInlineMessage instances
22	 * sharing the same hardcoded testid would collide.
23	 */
24	import React from 'react';
25	import { describe, test, expect, vi } from 'vitest';
26	import { render, screen } from '@testing-library/react';
27	import { ChakraProvider } from '@chakra-ui/react';
28	import theme from 'app/theme';
29	import { ZimmInlineMessage } from '.';
30	
31	vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
32	  ZimmIcon: (props: { type: string }) => <div data-testid="mock-info-icon" data-type={props.type} />,
33	}));
34	
35	const renderWithTheme = (ui: React.ReactElement) => render(<ChakraProvider theme={theme}>{ui}</ChakraProvider>);
36	
37	describe('ZimmInlineMessage', () => {
38	  test('renders the given text verbatim', () => {
39	    renderWithTheme(<ZimmInlineMessage variant="error" text="This item is unavailable" />);
40	    expect(screen.getByText('This item is unavailable')).toBeInTheDocument();
41	  });
42	
43	  test('carries aria-live="polite" so a shopper using assistive tech is told about it without a focus move', () => {
44	    renderWithTheme(<ZimmInlineMessage variant="warning" text="Maximum purchase quantity reached for this size" />);
45	    expect(screen.getByTestId('zimm-inline-message')).toHaveAttribute('aria-live', 'polite');
46	  });
47	
48	  test('error and warning variants resolve to genuinely different colours, not just different variant keys', () => {
49	    const { unmount } = renderWithTheme(<ZimmInlineMessage variant="error" text="Quantity unavailable in this size" />);
50	    const errorColor = getComputedStyle(screen.getByTestId('zimm-inline-message')).color;
51	    unmount();
52	
53	    renderWithTheme(<ZimmInlineMessage variant="warning" text="Quantity unavailable in this size" />);
54	    const warningColor = getComputedStyle(screen.getByTestId('zimm-inline-message')).color;
55	
56	    expect(errorColor).not.toBe(warningColor);
57	  });
58	
59	  // SFCC-795 rework pass criterion: warning carries the icon, confirmed against the 3 Figma
60	  // cart-item instances cited in this component's own docblock and in zimmInlineMessage.css.ts.
61	  test('variant="warning" renders the info-solid icon', () => {
62	    renderWithTheme(<ZimmInlineMessage variant="warning" text="Maximum purchase quantity reached for this size" />);
63	    const icon = screen.getByTestId('mock-info-icon');
64	    expect(icon).toBeInTheDocument();
65	    expect(icon).toHaveAttribute('data-type', 'info-solid');
66	  });
67	
