202	/**
203	 * Generic right-anchored slide-in drawer shell — overlay, panel, and a Figma-matched size
204	 * variant (see ZimmDrawerSize), built on Chakra's Drawer primitive (focus trap, initial focus,
205	 * focus restore, body-scroll lock, and Escape/overlay-click-to-close all come from Chakra, not
206	 * hand-rolled).
207	 *
208	 * Pass `title` to render an inline header row (title text left, close button right) sized per the
209	 * Figma drawer/header frames. Omit `title` and pass `labelledBy`/`aria-label` instead for drawers
210	 * that supply their own header (e.g. ZimmPdpDrawer's tab row), which keeps the floating close
211	 * button behaviour.
212	 *
213	 * @param props see ZimmDrawerProps
214	 */
215	export const ZimmDrawer = (props: ZimmDrawerProps) => {
216	  const { isOpen, onClose, size, children, titleStyle = 'large', finalFocusRef, initialFocusRef } = props;
217	  const styles = useMultiStyleConfig(ZIMM_DRAWER_RECIPE, { variant: size });
218	  const titleId = useId();
219	
220	  // Figma-fidelity audit fix, 2026-09-19: without an explicit `initialFocusRef`, Chakra's Drawer
221	  // defaults to auto-focusing the first focusable descendant — for every real consumer that
222	  // doesn't set one (ZimmCartDrawer, ZimmPdpDrawer), that's the close button. Reproduced live:
223	  // when nothing has focus and no prior user interaction exists yet (confirmed exactly matching
224	  // how a Storybook story that mounts already-open behaves, and plausible for a real first
225	  // render too), the browser's native `:focus-visible` heuristic has no basis to rule out a
226	  // keyboard interaction and defaults to showing the ring — on the close button, on every open,
227	  // regardless of whether the shopper used a mouse, touch, or keyboard to get there. `panelRef`
228	  // gives Chakra a neutral target instead: the dialog's own panel, `tabIndex={-1}` so it's
229	  // programmatically focusable without joining the normal Tab order. This still satisfies the
230	  // real requirement (focus moves into the dialog immediately, so keyboard/AT users land
231	  // somewhere sane and Tab/Escape work correctly from there) without ever auto-focusing an
232	  // interactive element nobody actually interacted with. A consumer that explicitly passes its
233	  // own `initialFocusRef` (ZimmWishlistAuthDrawer, straight to its email field) is untouched —
234	  // this only changes the *default* Chakra would otherwise have picked.
235	  const panelRef = useRef<HTMLDivElement>(null);
236	
237	  const title = 'title' in props ? props.title : undefined;
238	  const labelledBy = !title && 'labelledBy' in props ? props.labelledBy : undefined;
239	  const ariaLabel = !title && 'aria-label' in props ? props['aria-label'] : undefined;
240	
241	  // SFCC-926 — tester reported body scroll still active while any drawer is open, allowing
242	  // the page behind the overlay to scroll alongside the drawer. ZimmDrawer bypasses Chakra's
243	  // own <DrawerContent>, so blockScrollOnMount may not fire. Locking body overflow explicitly
244	  // ensures only the drawer's internal scroll area is accessible while it is open.
245	  // Uses the module-level counter so multiple open instances don't race to restore overflow.
246	  useEffect(() => {
247	    if (!isOpen) return;
248	    if (scrollLockCount === 0) {
249	      scrollLockPrev = document.body.style.overflow;
250	      document.body.style.overflow = 'hidden';
251	    }
252	    scrollLockCount++;
253	    return () => {
254	      scrollLockCount--;
255	      if (scrollLockCount === 0) {
256	        document.body.style.overflow = scrollLockPrev;
257	        scrollLockPrev = '';
258	      }
259	    };
260	  }, [isOpen]);
261	
262	  // Chakra's FocusLock remains active during the exit animation, so any focus call made
263	  // while the drawer is still mounted (rAF, close-button onClick) gets trapped and dropped.
264	  // onCloseComplete fires after the animation finishes and FocusLock is released — the only
265	  // reliable moment to restore focus. Covers both close-button click and Escape for all
266	  // consumers that pass finalFocusRef.
267	  const handleCloseComplete = () => {
268	    if (finalFocusRef) finalFocusRef.current?.focus();
269	  };

