// SFCC-795 plan step 3.6 (accessibility sweep) AC6: the rendered message and the stepper's two
// buttons share the same real id — the actual DOM-level proof of "programmatically associated",
// not just that some id and some aria-describedby exist independently somewhere in the tree.
test("message present: the message's id and both stepper buttons' aria-describedby are the exact same value", () => {
  renderWithProviders(
    <ProductItem product={MOCK_LINE_ITEM} message={{ variant: 'error', text: 'This item is unavailable' }} />,
  );

  const messageId = screen.getByTestId('zimm-inline-message').getAttribute('id');
  expect(messageId).toBeTruthy();
  expect(screen.getByRole('button', { name: DECREMENT_NAME })).toHaveAttribute('aria-describedby', messageId);
  expect(screen.getByRole('button', { name: INCREMENT_NAME })).toHaveAttribute('aria-describedby', messageId);
});

// SFCC-795 plan step 3.6: message omitted — guards against a regression where an id is
// generated and forwarded even with nothing to describe (useId() itself is called
// unconditionally per the rules of hooks; only the VALUE passed down to the message/stepper is
// conditional on `message` — see this component's own docblock).
test('message omitted: neither stepper button carries aria-describedby', () => {
  renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} />);

  expect(screen.getByRole('button', { name: DECREMENT_NAME })).not.toHaveAttribute('aria-describedby');
  expect(screen.getByRole('button', { name: INCREMENT_NAME })).not.toHaveAttribute('aria-describedby');
});

// SFCC-795 plan step 3.6: discountLabel is a separate ZimmInlineMessage instance and is
// deliberately NOT given this association (see the `message` prop's own JSDoc) — a discount is
// a property of the line item, not a quantity/availability state the stepper is responsible for.
test('discountLabel present but message absent: the discount label has no id, and the stepper has no aria-describedby', () => {
  renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} discountLabel="20% off applied" />);

  expect(screen.getByTestId('zimm-discount-label')).not.toHaveAttribute('id');

